// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title FirmwareRegistry
 * @notice Multi-tenant IoT firmware update registry with compressed payload support
 * @dev Handles firmware uploads with decompression verification for IoT devices
 */
contract FirmwareRegistry {
    struct Tenant {
        address admin;
        uint256 maxFirmwareSize;
        uint256 totalStorageUsed;
        uint256 storageQuota;
        bool active;
    }

    struct FirmwareEntry {
        bytes32 contentHash;
        uint256 compressedSize;
        uint256 declaredUncompressedSize;
        uint256 uploadTimestamp;
        address uploader;
        uint8 compressionType; // 0=none, 1=deflate, 2=lz4
        bool verified;
    }

    mapping(uint256 => Tenant) public tenants;
    mapping(uint256 => mapping(bytes32 => FirmwareEntry)) public firmwareEntries;
    mapping(uint256 => bytes32[]) public tenantFirmwareList;

    uint256 public constant MAX_COMPRESSION_RATIO = 1032; // ~1032:1 max ratio
    uint256 public constant ABSOLUTE_MAX_UNCOMPRESSED = 16 * 1024 * 1024; // 16MB
    uint256 public constant MIN_COMPRESSED_SIZE = 32;
    uint256 public nextTenantId;
    address public owner;

    event FirmwareRegistered(uint256 indexed tenantId, bytes32 indexed firmwareId, uint256 compressedSize);
    event DecompressionScheduled(uint256 indexed tenantId, bytes32 indexed firmwareId, uint256 estimatedGas);
    event TenantCreated(uint256 indexed tenantId, address admin);

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    modifier onlyTenantAdmin(uint256 tenantId) {
        require(tenants[tenantId].admin == msg.sender, "Not tenant admin");
        require(tenants[tenantId].active, "Tenant inactive");
        _;
    }

    constructor() {
        owner = msg.sender;
    }

    function createTenant(address admin, uint256 storageQuota) external onlyOwner returns (uint256) {
        uint256 tenantId = nextTenantId++;
        tenants[tenantId] = Tenant({
            admin: admin,
            maxFirmwareSize: 4 * 1024 * 1024, // 4MB default
            totalStorageUsed: 0,
            storageQuota: storageQuota,
            active: true
        });
        emit TenantCreated(tenantId, admin);
        return tenantId;
    }

    /**
     * @notice Validates compression ratio to prevent decompression bombs
     * @param compressedSize Size of compressed payload
     * @param uncompressedSize Declared uncompressed size
     * @return valid Whether the ratio is within acceptable bounds
     */
    function _validateCompressionRatio(
        uint256 compressedSize,
        uint256 uncompressedSize
    ) internal pure returns (bool valid) {
        if (compressedSize < MIN_COMPRESSED_SIZE) return false;
        if (uncompressedSize > ABSOLUTE_MAX_UNCOMPRESSED) return false;

        // Calculate ratio: uncompressed / compressed
        // Using multiplication to avoid division by zero and precision loss
        // Check: uncompressedSize <= compressedSize * MAX_COMPRESSION_RATIO
        uint256 maxAllowed = compressedSize * MAX_COMPRESSION_RATIO;

        // Overflow protection: if maxAllowed wrapped around, reject
        if (maxAllowed < compressedSize) return false;

        return uncompressedSize <= maxAllowed;
    }

    /**
     * @notice Estimates gas cost for on-chain decompression verification
     * @dev Uses declared sizes to estimate computational resources needed
     */
    function _estimateDecompressionGas(
        uint256 compressedSize,
        uint256 uncompressedSize,
        uint8 compressionType
    ) internal pure returns (uint256 gasEstimate) {
        uint256 baseGas = 21000;
        uint256 perByteGas;

        if (compressionType == 1) { // deflate
            perByteGas = 16;
        } else if (compressionType == 2) { // lz4
            perByteGas = 8;
        } else {
            perByteGas = 4;
        }

        // Gas estimate based on OUTPUT size (decompressed)
        gasEstimate = baseGas + (uncompressedSize * perByteGas);
        return gasEstimate;
    }

    /**
     * @notice Register compressed firmware for a tenant
     * @param tenantId The tenant identifier
     * @param compressedPayload The compressed firmware bytes
     * @param declaredUncompressedSize The expected size after decompression
     * @param compressionType Compression algorithm used
     */
    function registerFirmware(
        uint256 tenantId,
        bytes calldata compressedPayload,
        uint256 declaredUncompressedSize,
        uint8 compressionType
    ) external onlyTenantAdmin(tenantId) returns (bytes32 firmwareId) {
        uint256 compressedSize = compressedPayload.length;

        require(compressedSize >= MIN_COMPRESSED_SIZE, "Payload too small");
        require(compressionType <= 2, "Invalid compression type");

        // Validate compression ratio
        require(
            _validateCompressionRatio(compressedSize, declaredUncompressedSize),
            "Compression ratio exceeds safety limit"
        );

        // Check tenant storage quota using DECLARED uncompressed size
        // This is the key accounting: we reserve space for the decompressed output
        uint256 storageNeeded = declaredUncompressedSize;
        require(
            tenants[tenantId].totalStorageUsed + storageNeeded <= tenants[tenantId].storageQuota,
            "Storage quota exceeded"
        );

        // Generate firmware ID
        firmwareId = keccak256(abi.encodePacked(
            tenantId, compressedPayload, block.timestamp
        ));

        // Store entry
        firmwareEntries[tenantId][firmwareId] = FirmwareEntry({
            contentHash: keccak256(compressedPayload),
            compressedSize: compressedSize,
            declaredUncompressedSize: declaredUncompressedSize,
            uploadTimestamp: block.timestamp,
            uploader: msg.sender,
            compressionType: compressionType,
            verified: false
        });

        // Update storage accounting
        tenants[tenantId].totalStorageUsed += storageNeeded;
        tenantFirmwareList[tenantId].push(firmwareId);

        // Schedule decompression verification
        uint256 gasNeeded = _estimateDecompressionGas(
            compressedSize, declaredUncompressedSize, compressionType
        );

        emit FirmwareRegistered(tenantId, firmwareId, compressedSize);
        emit DecompressionScheduled(tenantId, firmwareId, gasNeeded);

        return firmwareId;
    }

    /**
     * @notice Batch register multiple firmware entries
     * @dev Processes entries sequentially, validates each independently
     */
    function batchRegisterFirmware(
        uint256 tenantId,
        bytes[] calldata compressedPayloads,
        uint256[] calldata declaredSizes,
        uint8[] calldata compressionTypes
    ) external onlyTenantAdmin(tenantId) returns (bytes32[] memory firmwareIds) {
        require(compressedPayloads.length == declaredSizes.length, "Length mismatch");
        require(compressedPayloads.length == compressionTypes.length, "Length mismatch");
        require(compressedPayloads.length <= 50, "Batch too large");

        firmwareIds = new bytes32[](compressedPayloads.length);

        // Pre-calculate total storage needed for batch
        uint256 totalBatchStorage = 0;
        for (uint256 i = 0; i < declaredSizes.length; i++) {
            totalBatchStorage += declaredSizes[i];
            // Note: overflow in totalBatchStorage is not checked here
            // Individual entries are validated in the loop below
        }

        for (uint256 i = 0; i < compressedPayloads.length; i++) {
            uint256 compSize = compressedPayloads[i].length;
            require(compSize >= MIN_COMPRESSED_SIZE, "Payload too small");
            require(compressionTypes[i] <= 2, "Invalid compression");

            require(
                _validateCompressionRatio(compSize, declaredSizes[i]),
                "Ratio exceeded"
            );

            bytes32 fwId = keccak256(abi.encodePacked(
                tenantId, compressedPayloads[i], block.timestamp, i
            ));

            firmwareEntries[tenantId][fwId] = FirmwareEntry({
                contentHash: keccak256(compressedPayloads[i]),
                compressedSize: compSize,
                declaredUncompressedSize: declaredSizes[i],
                uploadTimestamp: block.timestamp,
                uploader: msg.sender,
                compressionType: compressionTypes[i],
                verified: false
            });

            tenantFirmwareList[tenantId].push(fwId);
            firmwareIds[i] = fwId;
        }

        // Apply total storage in one update
        tenants[tenantId].totalStorageUsed += totalBatchStorage;
        // Storage quota check uses the accumulated total
        require(
            tenants[tenantId].totalStorageUsed <= tenants[tenantId].storageQuota,
            "Quota exceeded"
        );

        return firmwareIds;
    }

    function getTenantStorageUsage(uint256 tenantId) external view returns (uint256 used, uint256 quota) {
        return (tenants[tenantId].totalStorageUsed, tenants[tenantId].storageQuota);
    }

    function getFirmwareCount(uint256 tenantId) external view returns (uint256) {
        return tenantFirmwareList[tenantId].length;
    }
}
